// IMAP inbox -> analysis request. Accepts only mails whose subject starts with
// "check" (any case), e.g. "check CDR" or "check PKO PEO — co przed wynikami?".
// The filter is deliberately strict: this mailbox is reachable by anyone and every
// accepted mail spends one Claude Code call.
const ALLOWED_SENDERS = ['b.kolej@gmail.com'];   // edit here; empty array = anyone
const MAX_TICKERS = 3;
const MAX_BODY_CHARS = 1500;

const ZNANE = ['PKO','PEO','PKN','PZU','KGHM','KGH','DNP','ALE','CDR','LPP','EBP','SPL','PGE',
  'CPS','OPL','KTY','MBK','BDX','PCO','KRU','ALR','ZAB','JSW','CCC','EUR','GTC','TPE','ENG'];

// Santander Bank Polska to od 28.04.2026 Erste Bank Polska (skrót EBP) — SPL.WA zwraca
// w yfinance 404. Stary skrót zostaje rozpoznawany, ale pytamy już o nowy.
const PRZEMIANOWANE = { SPL: 'EBP' };

// "ALE" is both Allegro's ticker and a Polish conjunction, "EUR" a currency code.
const DWUZNACZNE = ['ALE', 'EUR'];
const WZOR = /\b[A-Z][A-Z0-9]{1,5}(?:\.US)?\b/g;

// The IMAP node ships different shapes depending on `format` (resolved = mailparser
// objects, simple = flat strings), so every field is read defensively.
function adres(pole) {
  if (!pole) { return ''; }
  if (Array.isArray(pole.value) && pole.value[0]) { return String(pole.value[0].address || ''); }
  const s = String(pole.text || pole.address || pole || '');
  const m = s.match(/<([^>]+)>/);
  return (m ? m[1] : s).trim();
}

function tekst(mail) {
  const raw = String(mail.text || mail.textPlain || '');
  if (raw) { return raw; }
  return String(mail.textAsHtml || mail.html || mail.textHtml || '')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<[^>]+>/g, ' ');
}

// Quoted history and signatures only add tokens and confuse the model.
function bezCytatow(body) {
  const out = [];
  for (const l of body.split('\n')) {
    if (/^\s*>/.test(l)) { continue; }
    if (/^\s*--\s*$/.test(l)) { break; }
    if (/^\s*(On .+ wrote:|W dniu .+ napisał)/i.test(l)) { break; }
    if (/^\s*Od:\s|^\s*From:\s/i.test(l)) { break; }
    out.push(l);
  }
  return out.join('\n').trim().slice(0, MAX_BODY_CHARS);
}

function rozpoznajTickery(text) {
  const zOryginalu = text.match(WZOR) || [];
  let tickers = [...new Set(zOryginalu.filter((t) => ZNANE.includes(t) || t.endsWith('.US')))];
  // Only when nothing matches do we retry case-insensitively ("check mbk"),
  // skipping the ambiguous tokens.
  if (tickers.length === 0) {
    const zWielkich = text.toUpperCase().match(WZOR) || [];
    tickers = [...new Set(zWielkich.filter(
      (t) => (ZNANE.includes(t) && !DWUZNACZNE.includes(t)) || t.endsWith('.US'),
    ))];
  }
  return [...new Set(tickers.map((t) => PRZEMIANOWANE[t] || t))].slice(0, MAX_TICKERS);
}

const zadania = [];
const odrzucone = [];

for (const item of $input.all()) {
  const mail = item.json;
  const temat = String(mail.subject || '').trim();
  const od = adres(mail.from).toLowerCase();

  // Loop guard: our own replies go out as "Re: check ..." and land back in this inbox.
  if (/^\s*(re|odp|fwd|fw)\s*:/i.test(temat)) { odrzucone.push(`${temat} (odpowiedź)`); continue; }
  if (!/^\s*check\b/i.test(temat)) { odrzucone.push(`${temat} (temat bez "check")`); continue; }
  if (ALLOWED_SENDERS.length && !ALLOWED_SENDERS.map((a) => a.toLowerCase()).includes(od)) {
    odrzucone.push(`${temat} (nadawca ${od})`);
    continue;
  }

  const tematPoCheck = temat.replace(/^\s*check\b[\s:—–-]*/i, '').trim();
  const tresc = bezCytatow(tekst(mail));
  // Tickers come from the subject first — the body may quote other companies.
  const zTematu = rozpoznajTickery(tematPoCheck);
  const tickers = zTematu.length ? zTematu : rozpoznajTickery(`${tematPoCheck}\n${tresc}`);

  if (!tickers.length) { odrzucone.push(`${temat} (brak tickera)`); continue; }

  // Subject minus the recognised tickers is the question ("check CDR przed Gamescomem?").
  // A bare "check CDR" gets the generic one — the body of such a mail is usually noise
  // ("dzieki", a signature), and passing that alone as the question derails the answer.
  const resztaTematu = tematPoCheck.replace(WZOR, ' ').replace(/[\s:—–-]+/g, ' ').trim();
  const pytanie = resztaTematu
    ? [resztaTematu, tresc].filter(Boolean).join('\n')
    : `Co z ${tickers.join(', ')}? Daj pełny obraz.${tresc ? `\n\nOd nadawcy: ${tresc}` : ''}`;

  zadania.push({
    json: {
      pytanie,
      tickers,
      toEmail: adres(mail.from),
      temat,
      messageId: String(mail.messageId || ''),
    },
  });
}

if (!zadania.length && odrzucone.length) {
  console.log(`Pominięte maile: ${odrzucone.join(' | ')}`);
}
return zadania;

// Same fetcher as the chat workflow — only the pass-through fields differ (the reply
// needs to know who asked). Keep the two in sync.
const pytanie = $json.pytanie;
const tickers = $json.tickers;
const base = 'http://stock-api:8000';
const H = this.helpers;
function sleep(ms) { return new Promise((r) => setTimeout(r, ms)); }

// Sequential — concurrency breaks yfinance (401 "Invalid Crumb"). One retry with backoff.
async function g(path) {
  for (let attempt = 0; attempt < 2; attempt++) {
    try { return await H.httpRequest({ url: base + path, json: true, timeout: 60000 }); }
    catch (e) {
      if (attempt === 0) { await sleep(1200); continue; }
      return { error: String((e && e.message) || e) };
    }
  }
}

// Sentiment is ~95% of the payload: one ticker ships 128 Google News items whose
// base64 redirect URLs alone cost ~10k tokens. Stripping them plus a 90-day window
// takes a ticker from ~33k to ~9k tokens — that is what blew the 1M limit.
const NEWS_WINDOW_DAYS = 90;
const MAX_MENTIONS_PER_SOURCE = 40;

function trimSentiment(s) {
  if (!s || !Array.isArray(s.results)) { return s; }
  const cutoff = Date.now() - NEWS_WINDOW_DAYS * 86400000;
  for (const src of s.results) {
    const mentions = Array.isArray(src.mentions) ? src.mentions : [];
    const dated = [];
    const undated = [];
    for (const m of mentions) {
      const t = m.date ? Date.parse(m.date) : NaN;
      if (Number.isNaN(t)) { undated.push(m); }        // Bankier ships no dates — keep them
      else if (t >= cutoff) { dated.push([t, m]); }
    }
    // Mentions arrive UNSORTED (Google News mixes in items from 2004), so sorting
    // before the cap is what makes the cap drop the oldest instead of random ones.
    dated.sort((a, b) => b[0] - a[0]);
    const kept = [...dated.map((p) => p[1]), ...undated].slice(0, MAX_MENTIONS_PER_SOURCE);
    src.mentions = kept.map((m) => {
      const { url, ...rest } = m;                       // URLs are never cited in the e-mail
      return rest;
    });
    src.mentions_shown = src.mentions.length;           // total_mentions/overall_score untouched
  }
  return s;
}

const macro = await g('/macro');
const spolki = [];
for (const t of tickers) {
  spolki.push({
    ticker: t,
    technical: await g(`/technical/${t}`),
    fundamental: await g(`/fundamental/${t}`),
    dcf: await g(`/dcf/${t}`),
    sentiment: trimSentiment(await g(`/sentiment/${t}`)),
    speculator: await g(`/speculator/${t}`),
  });
}

const kiedy = new Date().toLocaleString('pl-PL', { timeZone: 'Europe/Warsaw' });
const prompt =
  `PYTANIE UŻYTKOWNIKA: ${pytanie}\n\n` +
  `Data/godzina wywołania: ${kiedy}.\n` +
  `Rozpoznane spółki: ${tickers.join(', ')}.\n\n` +
  `KONTEKST MAKRO:\n${JSON.stringify(macro, null, 1)}\n\n` +
  `DANE SPÓŁEK:\n${JSON.stringify(spolki, null, 1)}`;

// Freshness is arithmetic over `quality` — computed here so the reply banner never
// depends on the model getting it right.
const quality = spolki.map((s) => ({
  ticker: s.ticker,
  last_date: ((s.technical || {}).data_quality || {}).last_date || null,
  is_stale: ((s.technical || {}).data_quality || {}).is_stale === true,
  missing_sessions: ((s.technical || {}).data_quality || {}).missing_sessions || 0,
  failed: Boolean((s.technical || {}).error),
}));

return [{
  json: {
    prompt,
    pytanie,
    tickers,
    quality,
    toEmail: $json.toEmail,
    temat: $json.temat,
    messageId: $json.messageId,
  },
}];

// Renders the reply: HTML (primary) + plain-text fallback.
// Styling mirrors the daily review mail — inline styles only, table layout, because
// Gmail/Outlook drop <style> blocks and ignore flex/grid.
const res = $input.first().json;
const zapytanie = $('Fetch data (sequential)').first().json;

const TZ = 'Europe/Warsaw';
const now = new Date();
const dzis = now.toLocaleDateString('pl-PL', { timeZone: TZ, day: '2-digit', month: '2-digit', year: 'numeric' });
const godzina = now.toLocaleTimeString('pl-PL', { timeZone: TZ, hour: '2-digit', minute: '2-digit' });

const FONT = "-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif";
const MONO = "ui-monospace,SFMono-Regular,Menlo,Consolas,'Liberation Mono',monospace";
const INK = '#1c2430';
const MUTED = '#5d6b7a';
const RULE = '#e4e8ed';

const HORIZONS = [
  { code: '7D', label: '7 dni' },
  { code: '2T', label: '2 tyg.' },
  { code: '1M', label: 'miesiąc' },
  { code: '3M', label: '3 mies.' },
  { code: '1R', label: 'rok' },
  { code: 'LT', label: 'długi term.' },
];
const VERDICTS = {
  KUPUJ: { mark: '▲', fg: '#0b6b3a', bg: '#e9f7ef', line: '#bfe3cd' },
  SPRZEDAJ: { mark: '▼', fg: '#a8201a', bg: '#fdecea', line: '#f3c7c3' },
  TRZYMAJ: { mark: '●', fg: '#8a6100', bg: '#fff7e6', line: '#f0dda8' },
  BRAK: { mark: '·', fg: '#7b8794', bg: '#f2f4f6', line: '#e0e4e9' },
};

const blad = res.error || !res.response ? String(res.error || 'brak odpowiedzi z proxy') : '';
const odpowiedz = blad ? '' : String(res.response);

// ── horizon block: "7D | KUPUJ | uzasadnienie" -> table ───────────────────────
// Pulled out of the markdown so it renders as a table instead of pipe-separated text.
const oceny = [];
const linieOdpowiedzi = [];
for (const l of odpowiedz.split('\n')) {
  const m = l.match(/^[\s*>-]*\**\s*(7D|2T|1M|3M|1R|LT)\s*\**\s*\|\s*\**\s*(KUPUJ|TRZYMAJ|SPRZEDAJ|BRAK DANYCH|BRAK)\s*\**\s*\|?\s*([\s\S]*)$/i);
  if (m) {
    oceny.push({
      code: m[1].toUpperCase(),
      verdict: m[2].toUpperCase().startsWith('BRAK') ? 'BRAK' : m[2].toUpperCase(),
      why: m[3].replace(/\**/g, '').trim(),
    });
    continue;
  }
  linieOdpowiedzi.push(l);
}
// Header of the dropped block ("Ocena w horyzontach") would dangle over an empty section.
const tresc = oceny.length
  ? linieOdpowiedzi.join('\n').replace(/(?:^|\n)[^\n]*ocena w horyzontach[^\n]*(?=\n|$)/gi, '')
  : odpowiedz;

// ── markdown -> HTML (headings, bold/italic/code, bullets, paragraphs) ────────
function esc(t) {
  return String(t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}
function inline(t) {
  return esc(t)
    .replace(/`([^`]+)`/g, `<code style="font-family:${MONO};font-size:12px;background:#f1f3f6;border-radius:3px;padding:1px 4px;">$1</code>`)
    .replace(/\*\*([^*]+)\*\*/g, '<strong style="color:' + INK + ';">$1</strong>')
    .replace(/(^|[\s(])\*([^*\n]+)\*/g, '$1<em>$2</em>');
}
function md(text) {
  const out = [];
  let para = [];
  let items = [];
  const P = `margin:0 0 10px;font-size:14px;line-height:1.62;color:${INK};`;
  const flushP = () => { if (para.length) { out.push(`<p style="${P}">${para.join('<br>')}</p>`); para = []; } };
  const flushL = () => {
    if (items.length) {
      out.push(`<ul style="margin:0 0 10px;padding-left:20px;">${items.map((i) => `<li style="${P}margin:0 0 5px;">${i}</li>`).join('')}</ul>`);
      items = [];
    }
  };
  for (const surowa of String(text || '').split('\n')) {
    const l = surowa.trim();
    if (!l) { flushP(); flushL(); continue; }
    // A free-form answer uses headings; the daily review never did, so this is extra here.
    const h = l.match(/^(#{1,4})\s+(.+?)\s*#*$/);
    if (h) {
      flushP(); flushL();
      const size = h[1].length <= 2 ? 16 : 14;
      out.push(`<div style="margin:18px 0 8px;font-size:${size}px;font-weight:700;color:${INK};border-bottom:1px solid ${RULE};padding-bottom:5px;">${inline(h[2])}</div>`);
      continue;
    }
    if (/^([-*_])\1{2,}$/.test(l)) { flushP(); flushL(); out.push(`<div style="height:1px;background:${RULE};margin:14px 0;"></div>`); continue; }
    const b = l.match(/^(?:[-*•·]|\d+[.)])\s+([\s\S]*)$/);
    if (b) { flushP(); items.push(inline(b[1])); continue; }
    flushL();
    para.push(inline(l));
  }
  flushP(); flushL();
  return out.join('') || `<p style="${P}">—</p>`;
}

// ── freshness banner (arithmetic over `quality`, never the model) ─────────────
const quality = Array.isArray(zapytanie.quality) ? zapytanie.quality : [];
const plData = (d) => { const m = String(d).match(/^(\d{4})-(\d{2})-(\d{2})/); return m ? `${m[3]}.${m[2]}.${m[1]}` : String(d); };
const daty = quality.map((q) => q.last_date).filter(Boolean).sort();
const sesja = daty.length ? plData(daty[daty.length - 1]) : null;
const nieswieze = quality
  .filter((q) => q.is_stale || q.missing_sessions >= 1)
  .map((q) => (q.missing_sessions ? `${q.ticker} (${q.missing_sessions})` : String(q.ticker)));
const bledy = quality.filter((q) => q.failed).map((q) => q.ticker);

const ostrzezenia = [];
if (blad) { ostrzezenia.push(`Analiza nie powstała: ${blad}`); }
if (nieswieze.length) { ostrzezenia.push(`Dane nieświeże: ${nieswieze.join(', ')}`); }
if (bledy.length) { ostrzezenia.push(`Brak danych technicznych: ${bledy.join(', ')}`); }

// ── HTML ──────────────────────────────────────────────────────────────────────
const tickery = (zapytanie.tickers || []).join(', ');
const H = [];
H.push(`<div style="background:#f5f7f9;padding:20px 12px;font-family:${FONT};">`);
H.push(`<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:680px;margin:0 auto;background:#ffffff;border:1px solid ${RULE};border-radius:10px;overflow:hidden;">`);

H.push(`<tr><td style="background:#1c2430;padding:18px 22px;">
  <div style="font-size:17px;font-weight:700;color:#ffffff;">Analiza na życzenie — ${esc(tickery || '?')}</div>
  <div style="font-size:12px;color:#9fb0c0;margin-top:4px;">${dzis}, godz. ${godzina}${sesja ? ` · ostatnia sesja ${sesja}` : ''}</div>
</td></tr>`);

H.push(`<tr><td style="padding:14px 22px;background:#fbfcfd;border-bottom:1px solid ${RULE};">
  <div style="font-size:11px;letter-spacing:.06em;text-transform:uppercase;color:${MUTED};margin-bottom:4px;">Twoje pytanie</div>
  <div style="font-size:13px;line-height:1.55;color:${INK};">${esc(zapytanie.pytanie || '').replace(/\n/g, '<br>')}</div>
</td></tr>`);

if (ostrzezenia.length) {
  H.push(`<tr><td style="padding:12px 22px;background:#fff7e6;border-bottom:1px solid #f0dda8;">
    <div style="font-size:13px;line-height:1.6;color:#8a6100;">⚠️ ${ostrzezenia.map(esc).join('<br>⚠️ ')}</div>
  </td></tr>`);
}

H.push(`<tr><td style="padding:20px 22px;">${md(blad ? 'Spróbuj wysłać maila jeszcze raz — dane z agentów przyszły, ale etap LLM nie odpowiedział.' : tresc)}`);

if (oceny.length) {
  const wiersze = HORIZONS.map((h) => {
    // A horizon the model skipped becomes an explicit "brak danych" row, never a gap.
    const o = oceny.find((x) => x.code === h.code) || { verdict: 'BRAK', why: '' };
    const v = VERDICTS[o.verdict] || VERDICTS.BRAK;
    return `<tr>
      <td style="padding:7px 10px;border-top:1px solid ${RULE};font-size:12px;color:${MUTED};white-space:nowrap;">${h.label}</td>
      <td style="padding:7px 10px;border-top:1px solid ${RULE};white-space:nowrap;">
        <span style="display:inline-block;padding:2px 8px;border-radius:11px;background:${v.bg};border:1px solid ${v.line};color:${v.fg};font-size:12px;font-weight:700;">${v.mark} ${o.verdict === 'BRAK' ? 'brak danych' : o.verdict.toLowerCase()}</span>
      </td>
      <td style="padding:7px 10px;border-top:1px solid ${RULE};font-size:13px;line-height:1.5;color:${INK};">${inline(o.why || '—')}</td>
    </tr>`;
  }).join('');
  H.push(`<div style="margin:18px 0 8px;font-size:14px;font-weight:700;color:${INK};">Ocena w horyzontach</div>
    <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border:1px solid ${RULE};border-radius:8px;border-collapse:separate;">${wiersze}</table>`);
}

H.push(`</td></tr>`);

H.push(`<tr><td style="padding:14px 22px;background:#fbfcfd;border-top:1px solid ${RULE};font-size:11px;line-height:1.6;color:${MUTED};">
  Odpowiedź na maila o temacie „${esc(zapytanie.temat || '')}". Kolejne pytanie wyślij z tematem
  <code style="font-family:${MONO};">check &lt;TICKER&gt;</code> (np. <code style="font-family:${MONO};">check CDR</code>),
  treść maila może zawierać doprecyzowanie.<br>
  To analiza danych, <strong>nie rekomendacja inwestycyjna</strong>.
</td></tr>`);

H.push('</table></div>');

// ── plain text ────────────────────────────────────────────────────────────────
const T = [];
T.push(`Analiza na życzenie — ${tickery} · ${dzis} ${godzina}${sesja ? ` · ostatnia sesja ${sesja}` : ''}`);
T.push('');
T.push(`Pytanie: ${zapytanie.pytanie}`);
if (ostrzezenia.length) { T.push(''); ostrzezenia.forEach((o) => T.push(`! ${o}`)); }
T.push('');
T.push(blad ? 'Analiza nie powstała — spróbuj ponownie.' : tresc.trim());
if (oceny.length) {
  T.push('');
  T.push('Ocena w horyzontach:');
  HORIZONS.forEach((h) => {
    const o = oceny.find((x) => x.code === h.code) || { verdict: 'BRAK', why: '' };
    const ocena = o.verdict === 'BRAK' ? 'brak danych' : o.verdict.toLowerCase();
    T.push(`  ${h.label.padEnd(12)} ${ocena}${o.why ? ` — ${o.why}` : ''}`);
  });
}
T.push('');
T.push('Kolejne pytanie: mail z tematem "check <TICKER>". To analiza danych, nie rekomendacja inwestycyjna.');

return [{
  json: {
    toEmail: zapytanie.toEmail,
    subject: `Re: ${zapytanie.temat}${blad ? ' — błąd' : ''} · ${dzis} ${godzina}`,
    html: H.join(''),
    text: T.join('\n'),
  },
}];
